INSERT INTO internal_message (
    org_id, receiver, title, content, business_id, 
    priority, is_read, create_time, read_time
) VALUES (
    #{orgId}, #{receiver}, #{title}, #{content}, #{businessId},
    #{priority}, #{isRead}, #{createTime}, #{readTime}
)

mapper.select:
SELECT
    id, org_id as orgId, receiver, title, content,
    business_id as businessId, priority, is_read as isRead,
    create_time as createTime, read_time as readTime
FROM internal_message
WHERE receiver = #{userId} AND org_id = #{orgId}

    AND is_read = #{isRead}

ORDER BY create_time DESC

    LIMIT #{limit}
